# -*- coding: utf-8 -*-
"""
P0-S1: strip tool fingerprints from a .docx produced by python-docx.

python-docx stamps every file it writes with its own default template, which
leaves three traces that have nothing to do with the paper and that a reader can
see in File > Properties:

  * docProps/core.xml   creator "python-docx", description "generated by
                        python-docx", and the template epoch 2013-12-23
  * docProps/app.xml    Application "Microsoft Macintosh Word", which is false
  * docProps/thumbnail.jpeg, customXml/*   parts of the default template

This script rewrites the archive with those parts removed and the remaining
metadata set to facts about the paper. It is idempotent.

Usage:  python s1_scrub_docx_metadata.py <file.docx> [<file.docx> ...]
"""
import os, re, sys, io, zipfile, shutil, datetime

CREATED = "2026-10-09T00:00:00Z"

# per-file metadata, keyed by basename
META = {
    "P0S1_JSTARS_v1.docx": (
        "Protocol Choices, Not Just Method Quality, Decide the Ranking: "
        "A Reproducibility Audit of Remote Sensing Super-Resolution Evaluation",
        "Dawei Liu",
    ),
    "P0S1_JSTARS_CoverLetter.docx": (
        "Cover Letter, IEEE JSTARS submission",
        "Dawei Liu",
    ),
}


def scrub(path):
    name = os.path.basename(path)
    title, author = META.get(name, ("", "Dawei Liu"))
    zin = zipfile.ZipFile(path)
    items = {i.filename: zin.read(i.filename) for i in zin.infolist()}
    infos = {i.filename: i for i in zin.infolist()}
    zin.close()

    removed = []

    # --- drop the template thumbnail and the customXml parts
    for k in list(items):
        if k == "docProps/thumbnail.jpeg" or k.startswith("customXml/"):
            del items[k]
            removed.append(k)

    def edit(part, fn):
        if part not in items:
            return
        txt = items[part].decode("utf-8")
        new = fn(txt)
        if new != txt:
            items[part] = new.encode("utf-8")

    # --- relationships pointing at the dropped parts
    RELNS = 'xmlns="http://schemas.openxmlformats.org/package/2006/relationships"'

    def fix_rels(txt):
        # self-heal: an earlier version of this script could drop the opening
        # element, because "<Relationships" starts with "<Relationship"
        if "<Relationships" not in txt:
            txt = re.sub(r"(<\?xml[^>]*\?>)",
                         r"\1\n<Relationships " + RELNS + ">", txt, count=1)
        m = re.search(r"<Relationships\b[^>]*>", txt)
        head = txt[:m.end()]
        kept = []
        for mm in re.finditer(r"<Relationship\b[^>]*/>", txt[m.end():]):
            tag = mm.group(0)
            if "thumbnail" in tag or "customXml" in tag:
                t = re.search(r'Target="([^"]*)"', tag)
                removed.append("rel:" + (t.group(1) if t else "?"))
                continue
            kept.append(tag)
        return head + "".join(kept) + "</Relationships>"

    edit("_rels/.rels", fix_rels)

    # --- content types: drop the Override entries that no longer have a part
    def fix_ct(txt):
        txt = re.sub(r"<Override[^>]*PartName=\"/customXml/[^\"]*\"[^>]*/>", "", txt)
        # jpeg default is only needed while thumbnail.jpeg is present
        if not any(k.endswith(".jpeg") for k in items):
            txt = re.sub(r"<Default Extension=\"jpeg\"[^>]*/>", "", txt)
        return txt

    edit("[Content_Types].xml", fix_ct)

    # --- core properties
    def fix_core(txt):
        txt = re.sub(r"<dc:creator>.*?</dc:creator>",
                     f"<dc:creator>{author}</dc:creator>", txt, flags=re.S)
        if "<dc:creator>" not in txt:
            txt = txt.replace("<cp:coreProperties", f"<dc:creator>{author}</dc:creator><cp:coreProperties", 1)
        txt = re.sub(r"<dc:title\s*/>", f"<dc:title>{title}</dc:title>", txt)
        txt = re.sub(r"<dc:title>.*?</dc:title>", f"<dc:title>{title}</dc:title>", txt, flags=re.S)
        txt = re.sub(r"<dc:description>.*?</dc:description>", "", txt, flags=re.S)
        txt = re.sub(r"<dc:description\s*/>", "", txt)
        txt = re.sub(
            r"<dcterms:created[^>]*>.*?</dcterms:created>",
            f'<dcterms:created xsi:type="dcterms:W3CDTF">{CREATED}</dcterms:created>',
            txt, flags=re.S)
        txt = re.sub(
            r"<dcterms:modified[^>]*>.*?</dcterms:modified>",
            f'<dcterms:modified xsi:type="dcterms:W3CDTF">{CREATED}</dcterms:modified>',
            txt, flags=re.S)
        txt = re.sub(r"<cp:revision>.*?</cp:revision>", "<cp:revision>1</cp:revision>", txt, flags=re.S)
        return txt

    edit("docProps/core.xml", fix_core)

    # --- extended properties
    def fix_app(txt):
        txt = re.sub(r"<Application>.*?</Application>", "", txt, flags=re.S)
        txt = re.sub(r"<Template>.*?</Template>", "", txt, flags=re.S)
        txt = re.sub(r"<TotalTime>.*?</TotalTime>", "<TotalTime>0</TotalTime>", txt, flags=re.S)
        return txt

    edit("docProps/app.xml", fix_app)

    # --- rewrite the archive, keeping part order
    order = [k for k in infos if k in items] + [k for k in items if k not in infos]
    tmp = path + ".tmp"
    with zipfile.ZipFile(tmp, "w", zipfile.ZIP_DEFLATED) as zout:
        for k in order:
            zout.writestr(k, items[k])
    shutil.move(tmp, path)
    return removed


if __name__ == "__main__":
    sys.stdout = io.TextIOWrapper(sys.stdout.buffer, encoding="utf-8")
    for p in sys.argv[1:]:
        if not os.path.exists(p):
            print("missing:", p)
            continue
        rem = scrub(p)
        print(f"scrubbed {os.path.basename(p)}  removed {len(rem)} part(s)")
        for r in rem:
            print("    -", r)
